<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('loyalty.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $action=$_POST['_action']??'adjust'; if($action==='adjust'){ $cid=(int)$_POST['customer_id']; $pts=(int)$_POST['points']; $acc=ensure_loyalty_account($cid); q('UPDATE loyalty_accounts SET points_balance=points_balance+?,lifetime_points=IF(? > 0,lifetime_points+?,lifetime_points),updated_at=NOW() WHERE id=?',[$pts,$pts,$pts,$acc]); q('INSERT INTO loyalty_transactions(account_id,transaction_type,points,description,created_by,created_at) VALUES(?,"adjustment",?,?,?,NOW())',[$acc,$pts,trim($_POST['description']??'Manual adjustment'),$_SESSION['user_id']]); flash('success','Points adjusted.');}
 if($action==='membership'){ $cid=(int)$_POST['customer_id']; $mid=(int)$_POST['membership_id']; $m=one('SELECT * FROM memberships WHERE id=? AND branch_id=?',[$mid,$bid]); if($m){q('INSERT INTO customer_memberships(branch_id,customer_id,membership_id,start_date,end_date,status,created_at) VALUES(?,?,?,?,?,"active",NOW())',[$bid,$cid,$mid,$_POST['start_date'],date('Y-m-d',strtotime($_POST['start_date'].' +'.(int)$m['duration_days'].' days'))]); flash('success','Membership assigned.');}} redirect('modules/loyalty.php');}
$rows=all('SELECT c.id,c.full_name,c.phone,COALESCE(la.points_balance,0) points,COALESCE(la.lifetime_points,0) lifetime FROM customers c LEFT JOIN loyalty_accounts la ON la.customer_id=c.id WHERE c.branch_id=? ORDER BY c.full_name',[$bid]); $title='Customer Loyalty'; $subtitle='Earn points, redeem discounts and assign memberships.'; include dirname(__DIR__).'/includes/header.php';?><div class="grid cols-2"><section class="card"><h2>Adjust Points</h2><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="adjust"><div class="form-grid"><div class="form-group"><label>Customer</label><select name="customer_id" required><?php foreach(customers_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="form-group"><label>Points (+/-)</label><input type="number" name="points" required></div><div class="form-group full"><label>Description</label><input name="description"></div></div><button class="btn">Save Adjustment</button></form></section><section class="card"><h2>Assign Membership</h2><form method="post"><?=csrf_field()?><input type="hidden" name="_action" value="membership"><div class="form-grid"><div class="form-group"><label>Customer</label><select name="customer_id" required><?php foreach(customers_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="form-group"><label>Plan</label><select name="membership_id" required><?php foreach(option_rows('memberships','name','branch_id=? AND status="active"') as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="form-group"><label>Start Date</label><input type="date" name="start_date" value="<?=e(today())?>"></div></div><button class="btn">Assign</button></form></section></div><h2>Customer Balances</h2><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Balance</th><th>Lifetime</th><th>History</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['points'])?></td><td><?=e($r['lifetime'])?></td><td><a class="btn small light" href="customer_view.php?id=<?=e($r['id'])?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>